{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE FUNCTION RUBYSORGANICS_DB.MAPLEMONK.SOLVE_BOGO_SUBSET_SUM_JS( ITEM_MRPS_JSON STRING, TARGET_DISCOUNT FLOAT ) RETURNS STRING LANGUAGE JAVASCRIPT STRICT AS $$ if (TARGET_DISCOUNT === null || TARGET_DISCOUNT === undefined || !ITEM_MRPS_JSON) { return JSON.stringify([]); } var target = Math.abs(Number(TARGET_DISCOUNT)); if (target <= 0) { return JSON.stringify([]); } var items; try { items = JSON.parse(ITEM_MRPS_JSON); } catch (e) { return JSON.stringify([]); } if (!Array.isArray(items)) { return JSON.stringify([]); } var expanded = []; for (var i = 0; i < items.length; i++) { var it = items[i]; if (it && typeof it.mrp === \'number\' && it.mrp > 0 && it.line_id) { var q = (typeof it.qty === \'number\' && Math.abs(it.qty) > 0) ? Math.abs(Math.round(it.qty)) : 1; for (var k = 0; k < q; k++) { expanded.push({ line_id: String(it.line_id), mrp: Number(it.mrp) }); } } } if (expanded.length === 0) { return JSON.stringify([]); } var tolerance = Math.max(5.0, 0.02 * target); var n = expanded.length; var bestExactCombo = []; var bestExactDiff = Infinity; var bestUnderCombo = []; var bestUnderSum = 0; function search(idx, currentSum, currentCombo) { var diff = Math.abs(currentSum - target); if (diff < bestExactDiff) { bestExactDiff = diff; bestExactCombo = currentCombo.slice(); if (bestExactDiff <= 0.01) { return true; } } if (currentSum > 0 && currentSum <= target + 1.0) { if (currentSum > bestUnderSum) { bestUnderSum = currentSum; bestUnderCombo = currentCombo.slice(); } } if (idx >= n || (currentSum - target) > (tolerance + 10.0)) { return false; } for (var j = idx; j < n; j++) { if (search(j + 1, currentSum + expanded[j].mrp, currentCombo.concat([expanded[j].line_id]))) { return true; } } return false; } search(0, 0.0, []); if (bestExactDiff <= tolerance) { return JSON.stringify(bestExactCombo); } if (bestUnderCombo.length > 0 && bestUnderSum > 0) { return JSON.stringify(bestUnderCombo); } return JSON.stringify([]); $$; CREATE OR REPLACE VIEW RUBYSORGANICS_DB.MAPLEMONK.VW_SHOPIFY_PARSED_DISCOUNT_CODES AS WITH order_base AS ( SELECT ORDER_NAME, MAX(DISCOUNT_CODE) AS DISCOUNT_CODE, MAX(TAGS) AS TAGS FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS GROUP BY ORDER_NAME ), parsed_note_attributes AS ( SELECT ORDER_NAME, ARRAY_AGG(DISTINCT UPPER(TRIM(SPLIT_PART(f.value:name::STRING, \'|\', 2)))) AS ATTR_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => NOTE_ATTRIBUTES) f WHERE LOWER(f.value:name::STRING) LIKE \'discount |%\' GROUP BY ORDER_NAME ), parsed_tags AS ( SELECT ORDER_NAME, ARRAY_AGG(DISTINCT UPPER(TRIM(t.value::STRING))) AS TAG_CODES FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS, LATERAL FLATTEN(INPUT => SPLIT(TAGS, \',\')) t WHERE UPPER(TRIM(t.value::STRING)) IN ( \'BUNDLE3\', \'BUNDLE4\', \'HELLORUBY\', \'LIPDAYBOGO\', \'FIRST999\', \'RUBY999\', \'RUBYFLASH\', \'HELLOHYDRA\', \'MISSEDYA25\', \'MYSTERYGIFT\', \'VIP15\', \'EMPLOYEEDISCOUNT50\', \'FREEGIFT\', \'FREEMINIPUFF\', \'MONSOON SALE: BOGO!\', \'MONSOON SALE: BOGO\', \'MONSOON SALE: BUY 1 GET 1 FREE\', \'FESTIVE SALE: BOGO\', \'PAYDAY SALE: BUY 1 GET 1 FREE\', \'SUMMER SALE - BUY 1 GET 1 FREE!\' ) GROUP BY ORDER_NAME ) SELECT b.ORDER_NAME, COALESCE( NULLIF( TRIM( ARRAY_TO_STRING( ARRAY_DISTINCT( ARRAY_CAT( COALESCE(na.ATTR_CODES, ARRAY_CONSTRUCT()), ARRAY_CAT( CASE WHEN TRIM(COALESCE(b.DISCOUNT_CODE, \'\')) <> \'\' THEN ARRAY_CONSTRUCT(UPPER(TRIM(b.DISCOUNT_CODE))) ELSE ARRAY_CONSTRUCT() END, COALESCE(pt.TAG_CODES, ARRAY_CONSTRUCT()) ) ) ), \' + \' ) ), \'\' ), \'No discount\' ) AS ALL_DISCOUNT_CODES_APPLIED FROM order_base b LEFT JOIN parsed_note_attributes na ON b.ORDER_NAME = na.ORDER_NAME LEFT JOIN parsed_tags pt ON b.ORDER_NAME = pt.ORDER_NAME; CREATE OR REPLACE TRANSIENT TABLE RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE AS WITH line_base AS ( SELECT s.ORDER_NAME, s.ORDER_TIMESTAMP::DATE AS ORDER_DATE, s.LINE_ITEM_ID::STRING AS LINE_ITEM_ID, TRIM(SPLIT_PART(s.PRODUCT_NAME, \' - \', 1)) AS BASE_PRODUCT_NAME, s.CATEGORY, CASE WHEN s.IS_REFUND = 1 OR LOWER(s.ORDER_STATUS) = \'cancelled\' THEN -1 * ABS(COALESCE(NULLIF(s.REFUND_QUANTITY, 0), s.QUANTITY, 1)) WHEN COALESCE(s.QUANTITY, 0) = 0 THEN -1 * ABS(COALESCE(s.REFUND_QUANTITY, 1)) ELSE s.QUANTITY END AS EFFECTIVE_QTY, CASE WHEN s.IS_REFUND = 1 OR LOWER(s.ORDER_STATUS) = \'cancelled\' THEN -1 * ABS(COALESCE(s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, 0) - COALESCE(s.DISCOUNT, 0)) ELSE COALESCE(s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, 0) - COALESCE(s.DISCOUNT, 0) END AS PAID_SELLING_PRICE, s.GROSS_SALES_BEFORE_TAX, s.GROSS_SALES_AFTER_TAX, s.TOTAL_SALES, s.QUANTITY, s.DISCOUNT, s.DISCOUNT_BEFORE_TAX, s.TAX, s.IS_REFUND, s.REFUND_QUANTITY, dc.ALL_DISCOUNT_CODES_APPLIED FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS s LEFT JOIN RUBYSORGANICS_DB.MAPLEMONK.VW_SHOPIFY_PARSED_DISCOUNT_CODES dc ON s.ORDER_NAME = dc.ORDER_NAME ) SELECT l.*, COALESCE(REPLACE(m.\"MRP\", \',\', \'\')::FLOAT, 0) AS UNIT_MRP, COALESCE(m.\"FREEBIE COGS\"::FLOAT, 0) AS UNIT_FREEBIE_COGS, COALESCE(m.\"FREEBIE BOGO\"::FLOAT, 0) AS UNIT_FREEBIE_BOGO, CASE WHEN l.GROSS_SALES_BEFORE_TAX = 0 AND l.TAX = 0 AND l.DISCOUNT > 0 AND COALESCE(m.\"FREEBIE BOGO\"::FLOAT, 0) > 0 AND ABS(l.DISCOUNT - COALESCE(REPLACE(m.\"MRP\", \',\', \'\')::FLOAT, 0)) <= 2.0 THEN LEAST(ABS(l.EFFECTIVE_QTY), ROUND(l.DISCOUNT / NULLIF(COALESCE(REPLACE(m.\"MRP\", \',\', \'\')::FLOAT, 0), 0))) ELSE 0 END AS EXPLICIT_FREE_BOGO_QTY FROM line_base l LEFT JOIN RUBYSORGANICS_DB.MAPLEMONK.gs_mrp_cogs_sheet1 m ON UPPER(TRIM(l.BASE_PRODUCT_NAME)) = UPPER(TRIM(m.\"Product Title\")); CREATE OR REPLACE TRANSIENT TABLE RUBYSORGANICS_DB.MAPLEMONK.TEMP_SOLVED_BOGO_LINES AS WITH orders_needing_solve AS ( SELECT ORDER_NAME, ABS(SUM(COALESCE(NULLIF(DISCOUNT, 0), DISCOUNT_BEFORE_TAX * 1.18, 0))) AS BOGO_TARGET_DISCOUNT, ARRAY_AGG( OBJECT_CONSTRUCT( \'line_id\', LINE_ITEM_ID, \'mrp\', UNIT_MRP, \'qty\', ABS(EFFECTIVE_QTY) ) ) AS ITEMS_JSON FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE WHERE UNIT_FREEBIE_BOGO > 0 AND UNIT_MRP > 0 AND ABS(EFFECTIVE_QTY) > 0 AND ( UPPER(ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BOGO%\' OR UPPER(ALL_DISCOUNT_CODES_APPLIED) LIKE \'%BUY 1 GET 1 FREE%\' ) GROUP BY ORDER_NAME HAVING SUM(EXPLICIT_FREE_BOGO_QTY) = 0 ), udf_execution AS ( SELECT ORDER_NAME, PARSE_JSON( RUBYSORGANICS_DB.MAPLEMONK.SOLVE_BOGO_SUBSET_SUM_JS( ITEMS_JSON::STRING, BOGO_TARGET_DISCOUNT::FLOAT ) ) AS SOLVED_LINE_IDS_ARRAY FROM orders_needing_solve ), flattened_lines AS ( SELECT u.ORDER_NAME, f.value::STRING AS FREE_LINE_ITEM_ID FROM udf_execution u, LATERAL FLATTEN(INPUT => u.SOLVED_LINE_IDS_ARRAY) f ) SELECT ORDER_NAME, FREE_LINE_ITEM_ID, COUNT(*) AS SOLVED_FREE_BOGO_QTY FROM flattened_lines GROUP BY ORDER_NAME, FREE_LINE_ITEM_ID; CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_LINE_ITEM_DISCOUNTING_FACT AS SELECT b.ORDER_NAME, b.ORDER_DATE, b.LINE_ITEM_ID, b.BASE_PRODUCT_NAME, b.UNIT_MRP, b.UNIT_FREEBIE_COGS, b.UNIT_FREEBIE_BOGO, b.EFFECTIVE_QTY AS QTY, CASE WHEN b.IS_REFUND = 1 OR b.EFFECTIVE_QTY < 0 THEN b.EFFECTIVE_QTY ELSE 0 END AS REVERSED_QTY, b.PAID_SELLING_PRICE, CASE WHEN b.EXPLICIT_FREE_BOGO_QTY > 0 THEN b.EXPLICIT_FREE_BOGO_QTY WHEN s.SOLVED_FREE_BOGO_QTY IS NOT NULL THEN s.SOLVED_FREE_BOGO_QTY ELSE 0 END AS FREE_BOGO_QTY, (b.EFFECTIVE_QTY - (SIGN(b.EFFECTIVE_QTY) * FREE_BOGO_QTY)) AS PAID_QTY, (FREE_BOGO_QTY * b.UNIT_FREEBIE_BOGO * SIGN(b.EFFECTIVE_QTY)) AS FREEBIE_BOGO_VALUE, (b.EFFECTIVE_QTY * b.UNIT_FREEBIE_COGS) AS FREEBIE_GWP_VALUE, ((b.EFFECTIVE_QTY - (SIGN(b.EFFECTIVE_QTY) * FREE_BOGO_QTY)) * b.UNIT_MRP) AS ADJUSTED_LINE_MRP_VALUE, b.ALL_DISCOUNT_CODES_APPLIED, b.IS_REFUND, b.REFUND_QUANTITY FROM RUBYSORGANICS_DB.MAPLEMONK.TEMP_LINE_ITEM_BASE b LEFT JOIN RUBYSORGANICS_DB.MAPLEMONK.TEMP_SOLVED_BOGO_LINES s ON b.ORDER_NAME = s.ORDER_NAME AND b.LINE_ITEM_ID = s.FREE_LINE_ITEM_ID; CREATE OR REPLACE TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_ORDER_DISCOUNTING_SUMMARY AS WITH order_aggregates AS ( SELECT ORDER_NAME, MIN(ORDER_DATE) AS ORDER_DATE, MAX(ALL_DISCOUNT_CODES_APPLIED) AS DISCOUNT_CODE, SUM(PAID_SELLING_PRICE) AS PAID_TOTAL, SUM(ADJUSTED_LINE_MRP_VALUE) AS GROSS_MRP, SUM(FREEBIE_GWP_VALUE) AS TOTAL_FREEBIE_GWP, SUM(FREEBIE_BOGO_VALUE) AS TOTAL_FREEBIE_BOGO, SUM(QTY) AS SUM_OF_QUANTITY, SUM(REVERSED_QTY) AS SUM_OF_REVERSED_QUANTITY FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_LINE_ITEM_DISCOUNTING_FACT GROUP BY ORDER_NAME ) SELECT ORDER_NAME, ORDER_DATE, DISCOUNT_CODE, CASE WHEN ABS(PAID_TOTAL) < 0.01 AND (UPPER(DISCOUNT_CODE) LIKE \'%BOGO%\' OR UPPER(DISCOUNT_CODE) LIKE \'%BUY 1 GET 1 FREE%\') THEN 1 ELSE 0 END AS ZERO_TOTAL_BOGO_FLAG, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE PAID_TOTAL END AS TOTAL, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE GROSS_MRP END AS MRP, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE (GROSS_MRP - PAID_TOTAL) END AS DISCOUNT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 OR GROSS_MRP = 0 THEN 0 ELSE (GROSS_MRP - PAID_TOTAL) / NULLIF(GROSS_MRP, 0) END AS DISCOUNT_PCT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE TOTAL_FREEBIE_GWP END AS FREEBIE_GWP, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE TOTAL_FREEBIE_BOGO END AS FREEBIE_BOGO, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE ((GROSS_MRP - PAID_TOTAL) + TOTAL_FREEBIE_GWP + TOTAL_FREEBIE_BOGO) END AS TOTAL_DISCOUNT_PLUS_FREEBIE, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 OR GROSS_MRP = 0 THEN 0 ELSE ((GROSS_MRP - PAID_TOTAL) + TOTAL_FREEBIE_GWP + TOTAL_FREEBIE_BOGO) / NULLIF(GROSS_MRP, 0) END AS TOTAL_DISCOUNT_PLUS_FREEBIE_PCT, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE SUM_OF_QUANTITY END AS SUM_OF_QUANTITY, CASE WHEN ZERO_TOTAL_BOGO_FLAG = 1 THEN 0 ELSE SUM_OF_REVERSED_QUANTITY END AS SUM_OF_REVERSED_QUANTITY FROM order_aggregates;",
                    "transaction": true
                }
            ) }}
